parameters.query:
SELECT table_name, schema_json, joins, allowed_ops
FROM crud_models
WHERE table_name = $1 AND is_active = true;

options.queryReplacement:
=={{ (() => {
  const empty = (v) => (v === '' || v === undefined) ? null : v;
  const causa = $fromAI('causa_mortandad', 'Cause of death — must be exactly one of: ENFERMEDAD, ACCIDENTE, DEPREDACIÓN, DESCONOCIDA, NATURAL', 'string');
  const fecha = $fromAI('fecha_evento', 'Date of death in YYYY-MM-DD format. If the user says "today" or "hoy", use the current date.', 'string');
  const desc  = $fromAI('descripcion', 'Free-text details about the death, if the user provided any. Omit if none given.', 'string');
  return [
    $fromAI('electronic_rfid', 'Electronic RFID / chip identifier, if the user provided this one specifically. Omit if not mentioned.', 'string'),
    $fromAI('rfid_siniiga', 'SINIIGA ear tag number, if the user provided this one specifically. Omit if not mentioned.', 'string'),
    $fromAI('numero_fuego', 'Fire brand / internal management number, if the user provided this one specifically. Omit if not mentioned.', 'string'),
    $fromAI('tenant_id', 'ID del rancho / tenant_id actual del usuario, tal como aparece en el contexto de sesión', 'number'),
    JSON.stringify({ causa_mortandad: causa, fecha_evento: fecha, descripcion: desc }),
    empty($fromAI('livestock_id', 'UUID of the animal, ONLY if obtained from a prior find_calf_by_dam call (never ask the user to say this out loud). Omit if using electronic_rfid/rfid_siniiga/numero_fuego instead.', 'string')),
    $fromAI('user_email', 'Email verificado del usuario, tal como aparece literalmente en las instrucciones del sistema', 'string')
  ];
})() }}

