={{ (() => {
  const empty = (v) => (v === '' || v === undefined) ? null : v;
  const species = $fromAI('species', "Animal species: BOVINO, BUFALO, BORREGO, or EQUIDO. Defaults to BOVINO if the user doesn't specify.", 'string') || 'BOVINO';
  return [
    $fromAI('tenant_id', 'ID del rancho / tenant_id actual del usuario, tal como aparece en el contexto de sesión', 'number'),
    $fromAI('calf_sex', 'MACHO or HEMBRA — must be exactly one of these two values, ask the user if unclear, never guess', 'string'),
    species,
    empty($fromAI('dam_id', 'UUID of the dam, ONLY if already resolved via a prior get_livestock_info call. Omit entirely if not resolved.', 'string')),
    empty($fromAI('dam_ear_tag', 'SINIIGA ear tag of the dam, as free text, if she could not be resolved to a UUID. Omit if dam_id was provided instead.', 'string')),
    empty($fromAI('dam_fire_number', 'Fire brand number of the dam, as free text, alternative to dam_ear_tag. Omit if dam_id or dam_ear_tag was already provided.', 'string')),
    $fromAI('birth_date', 'Date of birth in YYYY-MM-DD format. If the user says "today"/"hoy", use the current date.', 'string'),
    empty($fromAI('lot_id', 'UUID of the lot, ONLY if already known/resolved. Omit if not known — do NOT ask the user for this, it is rarely used.', 'string')),
    empty($fromAI('production_unit_id', 'UUID of the production unit (UPP), ONLY if already known/resolved (e.g. from a prior lookup). Omit if not known.', 'string')),
    empty($fromAI('paddock_id', 'UUID of the paddock (potrero), if the user specified one. Omit if not mentioned.', 'string')),
    $fromAI('birth_weight_kg', 'Birth weight in kilograms, if the user mentioned one. Omit entirely if not mentioned.', 'number'),
    empty($fromAI('notes', 'Any additional free-text notes about the birth, if provided.', 'string')),
    $fromAI('user_email', 'Email verificado del usuario, tal como aparece literalmente en las instrucciones del sistema', 'string')
  ];
})() }}

